import { z } from 'zod';

export const MatchFormatSchema = z.enum(['T20', 'ODI', 'TEST', '100BALL']);
export const MatchStatusSchema = z.enum(['upcoming', 'live', 'completed', 'abandoned']);
export const TossDecisionSchema = z.enum(['bat', 'bowl']);
export const ExtrasTypeSchema = z.enum(['wide', 'noBall', 'bye', 'legBye', 'penalty']);
export const WicketTypeSchema = z.enum([
  'bowled',
  'caught',
  'lbw',
  'run out',
  'stumped',
  'hit wicket',
  'retired hurt',
  'obstructing field',
  'timed out',
  'handled ball',
]);

export const TeamSchema = z.object({
  id: z.string(),
  name: z.string(),
  shortName: z.string(),
  code: z.string(),
  logoUrl: z.string().optional(),
  primaryColor: z.string().optional(),
});

export const PlayerSchema = z.object({
  id: z.string(),
  name: z.string(),
  shortName: z.string(),
  role: z.enum(['batter', 'bowler', 'allRounder', 'wicketKeeper']),
  avatarUrl: z.string().optional(),
});

export const DismissalSchema = z.object({
  type: WicketTypeSchema,
  bowlerId: z.string().optional(),
  bowlerName: z.string().optional(),
  fielderId: z.string().optional(),
  fielderName: z.string().optional(),
  text: z.string(),
});

export const BatterStatsSchema = z.object({
  id: z.string(),
  name: z.string(),
  runs: z.number().int().nonnegative(),
  balls: z.number().int().nonnegative(),
  fours: z.number().int().nonnegative(),
  sixes: z.number().int().nonnegative(),
  strikeRate: z.number().nonnegative(),
  isOut: z.boolean(),
  dismissal: DismissalSchema.optional(),
});

export const BowlerStatsSchema = z.object({
  id: z.string(),
  name: z.string(),
  overs: z.number().nonnegative(),
  maidens: z.number().int().nonnegative(),
  runs: z.number().int().nonnegative(),
  wickets: z.number().int().nonnegative(),
  economy: z.number().nonnegative(),
  wides: z.number().int().nonnegative(),
  noBalls: z.number().int().nonnegative(),
  dots: z.number().int().nonnegative(),
});

export const ExtrasBreakdownSchema = z.object({
  wides: z.number().int().nonnegative(),
  noBalls: z.number().int().nonnegative(),
  byes: z.number().int().nonnegative(),
  legByes: z.number().int().nonnegative(),
  penalty: z.number().int().nonnegative(),
  total: z.number().int().nonnegative(),
});

export const FallOfWicketSchema = z.object({
  wicketNumber: z.number().int().positive(),
  runs: z.number().int().nonnegative(),
  overs: z.number().nonnegative(),
  playerDismissedId: z.string(),
  playerDismissedName: z.string(),
});

export const PartnershipSchema = z.object({
  runs: z.number().int().nonnegative(),
  balls: z.number().int().nonnegative(),
  batter1Id: z.string(),
  batter1Name: z.string(),
  batter1Runs: z.number().int().nonnegative(),
  batter1Balls: z.number().int().nonnegative(),
  batter2Id: z.string(),
  batter2Name: z.string(),
  batter2Runs: z.number().int().nonnegative(),
  batter2Balls: z.number().int().nonnegative(),
});

export const BallEventSchema = z.object({
  sequence: z.number().int().nonnegative(),
  ballId: z.string(),
  matchId: z.string(),
  inningsId: z.string(),
  over: z.number().int().nonnegative(),
  ballInOver: z.number().int().positive(),
  legalBallNumber: z.number().int().positive(),
  displayOver: z.string(),
  strikerId: z.string(),
  strikerName: z.string(),
  nonStrikerId: z.string(),
  nonStrikerName: z.string(),
  bowlerId: z.string(),
  bowlerName: z.string(),
  runsBat: z.number().int().nonnegative(),
  extrasType: ExtrasTypeSchema.nullable().optional(),
  extrasRuns: z.number().int().nonnegative(),
  totalRuns: z.number().int().nonnegative(),
  isBoundary: z.boolean(),
  isFour: z.boolean(),
  isSix: z.boolean(),
  isWicket: z.boolean(),
  wicketType: WicketTypeSchema.optional(),
  dismissedPlayerId: z.string().optional(),
  dismissedPlayerName: z.string().optional(),
  commentary: z.string(),
  timestamp: z.number(),
});

export const OverSummarySchema = z.object({
  overNumber: z.number().int().nonnegative(),
  bowlerId: z.string(),
  bowlerName: z.string(),
  runs: z.number().int().nonnegative(),
  wickets: z.number().int().nonnegative(),
  balls: z.array(BallEventSchema),
});

export const InningsSchema = z.object({
  id: z.string(),
  matchId: z.string(),
  inningsNumber: z.number().int().positive(),
  battingTeamId: z.string(),
  bowlingTeamId: z.string(),
  runs: z.number().int().nonnegative(),
  wickets: z.number().int().nonnegative(),
  overs: z.number().nonnegative(),
  balls: z.number().int().nonnegative(),
  runRate: z.number().nonnegative(),
  targetRuns: z.number().int().positive().optional(),
  requiredRunRate: z.number().nonnegative().optional(),
  extras: ExtrasBreakdownSchema,
  batters: z.array(BatterStatsSchema),
  bowlers: z.array(BowlerStatsSchema),
  fallOfWickets: z.array(FallOfWicketSchema),
  isCompleted: z.boolean(),
});

export const WinProbabilityResultSchema = z.object({
  teamAId: z.string(),
  teamAName: z.string(),
  teamAProb: z.number().min(0).max(100),
  teamBId: z.string(),
  teamBName: z.string(),
  teamBProb: z.number().min(0).max(100),
  confidence: z.number().min(0).max(100),
  projectedScore: z.number().optional(),
  factors: z
    .object({
      ballsRemaining: z.number(),
      wicketsInHand: z.number(),
      requiredRunRate: z.number().optional(),
      currentRunRate: z.number(),
      parScore: z.number(),
    })
    .optional(),
});

export const ScoreSummarySchema = z.object({
  r: z.number().int().nonnegative(),
  w: z.number().int().nonnegative(),
  o: z.number().nonnegative(),
  inning: z.string(),
});

export const TeamScoreSummarySchema = z.object({
  runs: z.number().int().nonnegative(),
  wickets: z.number().int().nonnegative(),
  overs: z.number().nonnegative(),
  display: z.string(),
});

export const MatchSchema = z.object({
  id: z.string(),
  slug: z.string(),
  title: z.string(),
  seriesId: z.string(),
  seriesName: z.string(),
  format: MatchFormatSchema,
  status: MatchStatusSchema,
  statusText: z.string(),
  venue: z.string(),
  city: z.string(),
  startTime: z.string(),
  teamA: TeamSchema,
  teamB: TeamSchema,
  matchNumber: z.string().optional(),
  teamAScore: TeamScoreSummarySchema.optional(),
  teamBScore: TeamScoreSummarySchema.optional(),
  scores: z.array(ScoreSummarySchema).optional(),
  toss: z
    .object({
      winnerId: z.string(),
      decision: TossDecisionSchema,
      text: z.string(),
    })
    .optional(),
  winnerId: z.string().optional(),
  resultText: z.string().optional(),
  currentInningsNumber: z.number().int().positive(),
  hasSquad: z.boolean().optional(),
  fantasyEnabled: z.boolean().optional(),
  bbbEnabled: z.boolean().optional(),
});

export const MatchStateSchema = z.object({
  match: MatchSchema,
  currentInnings: InningsSchema,
  innings: z.array(InningsSchema),
  currentBatters: z.tuple([BatterStatsSchema, BatterStatsSchema]),
  currentBowler: BowlerStatsSchema,
  currentPartnership: PartnershipSchema,
  thisOver: z.array(BallEventSchema),
  lastOvers: z.array(OverSummarySchema),
  recentBalls: z.array(BallEventSchema),
  analytics: z.object({
    currentRunRate: z.number().nonnegative(),
    requiredRunRate: z.number().nonnegative().optional(),
    projectedScore: z.number().nonnegative().optional(),
    dotBallPercentage: z.number().min(0).max(100),
    boundaryPercentage: z.number().min(0).max(100),
    winProbability: WinProbabilityResultSchema,
  }),
  sequence: z.number().int().nonnegative(),
  stateHash: z.string(),
  lastUpdated: z.number(),
});

export const MatchDeltaEventSchema = z.object({
  sequence: z.number().int().nonnegative(),
  matchId: z.string(),
  timestamp: z.number(),
  type: z.enum(['ball', 'wicket', 'boundary', 'innings_break', 'match_end', 'state_sync']),
  ball: BallEventSchema.optional(),
  scoreChange: z
    .object({
      runs: z.number().int().nonnegative(),
      wickets: z.number().int().nonnegative(),
      overs: z.number().nonnegative(),
      currentRunRate: z.number().nonnegative(),
      requiredRunRate: z.number().nonnegative().optional(),
    })
    .optional(),
  winProbability: WinProbabilityResultSchema.optional(),
  message: z.string().optional(),
});

export const ScorecardSchema = z.object({
  match: MatchSchema,
  innings: z.array(InningsSchema),
});

export const CommentarySchema = z.object({
  id: z.string(),
  matchId: z.string(),
  sequence: z.number().int().nonnegative(),
  over: z.number().int().nonnegative(),
  ball: z.number().int().positive(),
  displayOver: z.string(),
  text: z.string(),
  runs: z.number().int().nonnegative(),
  isBoundary: z.boolean(),
  isWicket: z.boolean(),
  timestamp: z.number(),
});
